       <label class="checkbox-inline" data-toggle="tooltip" title="/api/public.php?show=time">\r\n                                        <input type="checkbox" name="public_list[]" value="time" id="time" checked><label for="time">统计时间</label>\r\n                                    </label>\r\n                                    <label class="checkbox-inline" data-toggle="tooltip" title="开启分离后仅统计游客上传<br />public.php?show=today">\r\n                                        <input type="checkbox" name="public_list[]" value="today" id="today" checked><label for="today">今日</label>\r\n                                    </label>\r\n                                    <label class="checkbox-inline" data-toggle="tooltip" title="开启分离后仅统计游客上传<br />public.php?show=yesterday">\r\n                                        <input type="checkbox" name="public_list[]" value="yesterday" id="yesterday" checked><label for="yesterday">昨日</label>\r\n                                    </label>\r\n                                    <label class="checkbox-inline" data-toggle="tooltip" title="public.php?show=total_space">\r\n                                        <input type="checkbox" name="public_list[]" value="total_space" id="total_space" checked><label for="total_space">总空间</label>\r\n                                    </label>\r\n                                    <label class="checkbox-inline" data-toggle="tooltip" title="public.php?show=used_space">\r\n                                        <input type="checkbox" name="public_list[]" value="used_space" id="used_space" checked><label for="used_space">已用</label>\r\n                                    </label>\r\n                                    <label class="checkbox-inline" data-toggle="tooltip" title="public.php?show=free_space">\r\n                                        <input type="checkbox" name="public_list[]" value="free_space" id="free_space" checked><label for="free_space">剩余</label>\r\n                                    </label>\r\n                                    <label class="checkbox-inline" data-toggle="tooltip" title="public.php?show=image_used">\r\n                                        <input type="checkbox" name="public_list[]" value="image_used" id="image_used" checked><label for="image_used">图片占用</label>\r\n                                    </label>\r\n                                    <label class="checkbox-inline" data-toggle="tooltip" title="public.php?show=file">\r\n                                        <input type="checkbox" name="public_list[]" value="file" id="file" checked><label for="file">文件数量</label>\r\n                                    </label>\r\n                                    <label class="checkbox-inline" data-toggle="tooltip" title="public.php?show=dir">\r\n                                        <input type="checkbox" name="public_list[]" value="dir" id="dir" checked><label for="dir">文件夹数量</label>\r\n                                    </label>\r\n                                    <label class="checkbox-inline" data-toggle="tooltip" title="开启分离后仅统计游客上传<br />public.php?show=month">\r\n                                        <input type="checkbox" name="public_list[]" value="month" id="month" checked><label for="month">最近30日上传</label>\r\n                                    </label>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    <div class="col-md-12">\r\n                        <div class="col-md-6">\r\n                            <div class="form-group">\r\n                                <label>缓存周期 | 当前: </label>\r\n                                <label id="cache_freq"></label><label>小时</label>\r\n                                <input type="range" class="form-control" name="cache_freq" value="" min="1" step="1" max="24" onchange="document.getElementById('cache_freq').innerHTML=value">\r\n                            </div>\r\n                        </div>\r\n                        <div class="col-md-6">\r\n                            <div class="form-group">\r\n                                <label>图片违规判断率 | 当前: </label>\r\n                                <label id="checkImg_value"></label><label>%</label>\r\n                                <input type="range" class="form-control" name="checkImg_value" value="" min="1" max="100" step="1" onchange="document.getElementById('checkImg_value').innerHTML=value">\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    <div class="col-md-12">\r\n                        <div class="col-md-4">\r\n                            <div class="form-group">\r\n                                <div class="input-group">\r\n                                    <span class="input-group-addon" data-toggle="tooltip" title="点击查看所支持的时区列表">自定义时区 <a href="https://www.php.net/manual/zh/timezones.php" target="_blank"><i class="icon icon-external-link"></i></a>\r\n                                    </span>\r\n                                    <input class="form-control" type="text" name="timezone" value="" data-toggle="tooltip" title="默认时区(中国·上海) Asia/Shanghai" required="required" onkeyup="this.value=this.value.replace(/\\s/g,'')">\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                        <div class="col-md-4">\r\n                            <div class="form-group">\r\n                                <div class="input-group" data-toggle="tooltip" title="请输入限制数量 | 0 为不限制<br /> 开启监黄,水印等受网络波动和机器性能,执行完毕前限制不生效!">\r\n                                    <span class="input-group-addon">游客上传限制</span>\r\n                                    <input class="form-control" type="number" name="ip_upload_counts" min="0" value="" required="required">\r\n                                    <span class="input-group-addon">张</span>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                        <div class="col-md-4">\r\n                            <div class="form-group">\r\n                                <div class="input-group" data-toggle="tooltip" title="使用nsfwjs方式需要自行搭建或使用开源接口 据说准确率能达到93%">\r\n                                    <span class="input-group-addon">图片鉴黄</span>\r\n                                    <select class="form-control" name="checkImg">\r\n                                        <option value="0" selected>关闭</option>\r\n                                        <option value="1" selected>moderatecontent | API 设置中填入Moderate Key</option>\r\n                                        <option value="2" selected title="">nsfwjs | API 设置中填入nsfwjs url</option>\r\n                                    </select>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    <div class="form-group">\r\n                        <input type="hidden" class="form-control" name="update" value="" placeholder="隐藏的保存">\r\n                    </div>\r\n                    <button type="submit" class="btn btn-primary">保存</button>\r\n                </form>\r\n            </div>\r\n        </div>\r\n        <div class="tab-pane fade" id="Content7">\r\n            <h5 class="header-dividing">可疑图片<small> 鉴黄查到的可疑图片</small></h5>\r\n            <p>key申请地址: <a href="https://client.moderatecontent.com/" target="_blank">https://client.moderatecontent.com/</a></p>\r\n            <p>获得key后打开->API 设置->Moderate Key->填入key</p>\r\n            <p>为了访问速度,仅显示最近10张图片;鉴黄需要在图床安全->图片鉴黄中开启</p>\r\n            <div class="table-responsive table-condensed">\r\n                <table class="table table-hover table-striped table-bordered">\r\n                    <thead>\r\n                        <tr>\r\n                            <th>